7:     if (state.session.server.forceSettings) {
8:       if (containsProperty(state.session.server, key)) {
9:         return state.session.server[key];
10:       }
11:       if (containsProperty(state.session.user, key)) {
12:         return state.session.user[key];
13:       }
14:       return defaultValue;
