1: import { useMemo } from 'react';
2: import { useAttributePreference } from '../../common/util/preferences';
3: import useMapLayer from '../core/useMapLayer';
4: import useMapOverlays from './useMapOverlays';
5: 
6: const MapOverlayLayer = ({ overlay }) => {
7:   useMapLayer({
8:     source: overlay.source,
9:     layers: [
10:       {
11:         type: 'raster',
12:         metadata: { 'traccar:title': overlay.title },
13:         layout: {
14:           visibility: 'visible',
15:         },
16:       },
17:     ],
18:     layersDeps: [overlay],
19:   });
20: 
21:   return null;
22: };
23: 
24: const MapOverlay = () => {
25:   const mapOverlays = useMapOverlays();
26:   const selectedMapOverlay = useAttributePreference('selectedMapOverlay');
27: 
28:   const activeOverlays = useMemo(() => {
29:     const selectedIds = selectedMapOverlay ? selectedMapOverlay.split(',') : [];
30:     return mapOverlays
31:       .filter((overlay) => overlay.available)
32:       .filter((overlay) => selectedIds.includes(overlay.id));
33:   }, [mapOverlays, selectedMapOverlay]);
34: 
35:   return activeOverlays.map((overlay) => <MapOverlayLayer key={overlay.id} overlay={overlay} />);
36: };
37: 
38: export default MapOverlay;
