10: const MapPositionMarkers = ({
11:   positions,
12:   onMapClick,
13:   onMarkerClick,
14:   showStatus,
15:   selectedPosition,
16:   titleField,
17:   disabled,
18: }) => {
19:   const devices = useSelector((state) => state.devices.items);
20:   const selectedDeviceId = useSelector((state) => state.devices.selectedId);
21: 
22:   const mapCluster = useAttributePreference('mapCluster', true);
23:   const directionType = useAttributePreference('mapDirection', 'selected');
24: 
25:   const onMapClickCallback = useCallback(
26:     (event) => {
27:       if (!event.defaultPrevented && onMapClick) {
28:         const [longitude, latitude] = fromMapCoordinates(event.lngLat.lng, event.lngLat.lat);
29:         onMapClick(latitude, longitude);
30:       }
31:     },
32:     [onMapClick],
33:   );
34: 
35:   useEffect(() => {
36:     map.on('click', onMapClickCallback);
37:     return () => map.off('click', onMapClickCallback);
38:   }, [onMapClickCallback]);
