40:   const buildMarker = (position) => {
41:     const device = devices[position.deviceId];
42:     let showDirection;
43:     switch (directionType) {
44:       case 'none':
45:         showDirection = false;
46:         break;
47:       case 'all':
48:         showDirection = position.course > 0;
49:         break;
50:       default:
51:         showDirection = selectedPosition?.id === position.id && position.course > 0;
52:         break;
53:     }
54:     const color = showStatus
55:       ? position.attributes.color || getStatusColor(device.status)
56:       : 'neutral';
57:     const titles = { name: device.name, fixTime: formatTime(position.fixTime, 'seconds') };
58:     return {
59:       id: position.id,
60:       deviceId: position.deviceId,
61:       latitude: position.latitude,
62:       longitude: position.longitude,
63:       image: `${mapIconKey(device.category)}-${color}`,
64:       title: titles[titleField || 'name'],
65:       rotation: position.course,
66:       direction: showDirection,
67:     };
68:   };
