70:   const markers = positions.filter((it) => devices.hasOwnProperty(it.deviceId)).map(buildMarker);
71: 
72:   const onClick = useCallback(
73:     (properties) => onMarkerClick?.(properties.id, properties.deviceId),
74:     [onMarkerClick],
75:   );
