56:           });
57:           setInitialized(true);
58:         }
59:       }
60:     }
61:   }, [
62:     selectedDeviceId,
63:     initialized,
64:     defaultLatitude,
65:     defaultLongitude,
66:     defaultZoom,
67:     positions,
68:     filteredPositions,
