1: import { useState } from 'react';
2: 
3: import {
4:   Button,
5:   Checkbox,
6:   OutlinedInput,
7:   FormControl,
8:   FormControlLabel,
9:   Grid,
10:   IconButton,
11:   InputAdornment,
12:   InputLabel,
13:   Accordion,
14:   AccordionSummary,
15:   Typography,
16:   AccordionDetails,
17: } from '@mui/material';
18: import CloseIcon from '@mui/icons-material/Close';
19: import AddIcon from '@mui/icons-material/Add';
20: import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
21: import AddAttributeDialog from './AddAttributeDialog';
22: import { useTranslation } from '../../common/components/LocalizationProvider';
23: import { useAttributePreference } from '../../common/util/preferences';
24: import {
25:   distanceFromMeters,
26:   distanceToMeters,
27:   distanceUnitString,
28:   speedFromKnots,
29:   speedToKnots,
30:   speedUnitString,
31:   volumeFromLiters,
32:   volumeToLiters,
33:   volumeUnitString,
34: } from '../../common/util/converter';
35: import useFeatures from '../../common/util/useFeatures';
36: import useSettingsStyles from '../common/useSettingsStyles';
37: 
38: const EditAttributesAccordion = ({
39:   attribute,
40:   attributes,
41:   setAttributes,
42:   definitions,
43:   focusAttribute,
44: }) => {
45:   const { classes } = useSettingsStyles();
46:   const t = useTranslation();
47: 
48:   const features = useFeatures();
49: 
50:   const speedUnit = useAttributePreference('speedUnit');
51:   const distanceUnit = useAttributePreference('distanceUnit');
52:   const volumeUnit = useAttributePreference('volumeUnit');
53: 
54:   const [addDialogShown, setAddDialogShown] = useState(false);
55: 
56:   const updateAttribute = (key, value, type, dataType) => {
57:     const updatedAttributes = { ...attributes };
58:     switch (dataType) {
59:       case 'speed':
60:         updatedAttributes[key] = speedToKnots(Number(value), speedUnit);
61:         break;
62:       case 'distance':
63:         updatedAttributes[key] = distanceToMeters(Number(value), distanceUnit);
64:         break;
65:       case 'volume':
66:         updatedAttributes[key] = volumeToLiters(Number(value), volumeUnit);
67:         break;
68:       default:
69:         updatedAttributes[key] = type === 'number' ? Number(value) : value;
70:         break;
71:     }
72:     setAttributes(updatedAttributes);
73:   };
74: 
75:   const deleteAttribute = (key) => {
76:     const updatedAttributes = { ...attributes };
77:     delete updatedAttributes[key];
78:     setAttributes(updatedAttributes);
79:   };
80: 
81:   const getAttributeName = (key, dataType) => {
82:     const definition = definitions[key];
83:     const name = definition ? definition.name : key;
84:     switch (dataType) {
85:       case 'speed':
86:         return `${name} (${speedUnitString(speedUnit, t)})`;
87:       case 'distance':
88:         return `${name} (${distanceUnitString(distanceUnit, t)})`;
89:       case 'volume':
90:         return `${name} (${volumeUnitString(volumeUnit, t)})`;
91:       default:
92:         return name;
93:     }
94:   };
95: 
96:   const getAttributeType = (value) => {
97:     if (typeof value === 'number') {
98:       return 'number';
99:     }
100:     if (typeof value === 'boolean') {
101:       return 'boolean';
102:     }
103:     return 'string';
104:   };
105: 
106:   const getAttributeDataType = (key) => {
107:     const definition = definitions[key];
108:     return definition && definition.dataType;
109:   };
110: 
111:   const getDisplayValue = (value, dataType) => {
112:     if (value !== undefined && value !== null) {
113:       switch (dataType) {
114:         case 'speed':
115:           return speedFromKnots(value, speedUnit);
116:         case 'distance':
117:           return distanceFromMeters(value, distanceUnit);
118:         case 'volume':
119:           return volumeFromLiters(value, volumeUnit);
120:         default:
121:           return value;
122:       }
123:     }
124:     return '';
125:   };
126: 
127:   const convertToList = (attributes) => {
128:     const booleanList = [];
129:     const otherList = [];
130:     const excludeAttributes = [
131:       'speedUnit',
132:       'distanceUnit',
133:       'altitudeUnit',
134:       'volumeUnit',
135:       'timezone',
136:     ];
137:     Object.keys(attributes || [])
138:       .filter((key) => !excludeAttributes.includes(key))
139:       .forEach((key) => {
140:         const value = attributes[key];
141:         const type = getAttributeType(value);
142:         const dataType = getAttributeDataType(key);
143:         if (type === 'boolean') {
144:           booleanList.push({
145:             key,
146:             value,
147:             type,
148:             dataType,
149:           });
150:         } else {
151:           otherList.push({
152:             key,
153:             value,
154:             type,
155:             dataType,
156:           });
157:         }
158:       });
159:     return [...otherList, ...booleanList];
160:   };
161: 
162:   const handleAddResult = (definition) => {
163:     setAddDialogShown(false);
164:     if (definition) {
165:       switch (definition.type) {
166:         case 'number':
167:           updateAttribute(definition.key, 0);
168:           break;
169:         case 'boolean':
170:           updateAttribute(definition.key, false);
171:           break;
172:         default:
173:           updateAttribute(definition.key, '');
174:           break;
175:       }
176:     }
177:   };
178: 
179:   return features.disableAttributes ? (
180:     ''
181:   ) : (
182:     <Accordion defaultExpanded={!!attribute}>
183:       <AccordionSummary expandIcon={<ExpandMoreIcon />}>
184:         <Typography variant="subtitle1">{t('sharedAttributes')}</Typography>
185:       </AccordionSummary>
186:       <AccordionDetails className={classes.details}>
187:         {convertToList(attributes).map(({ key, value, type, dataType }) => {
188:           if (type === 'boolean') {
189:             return (
190:               <Grid container direction="row" justifyContent="space-between" key={key}>
191:                 <FormControlLabel
192:                   control={
193:                     <Checkbox
194:                       checked={value}
195:                       onChange={(e) => updateAttribute(key, e.target.checked)}
196:                     />
197:                   }
198:                   label={getAttributeName(key, dataType)}
199:                 />
200:                 <IconButton
201:                   size="small"
202:                   className={classes.removeButton}
203:                   onClick={() => deleteAttribute(key)}
204:                 >
205:                   <CloseIcon fontSize="small" />
206:                 </IconButton>
207:               </Grid>
208:             );
209:           }
210:           return (
211:             <FormControl key={key}>
212:               <InputLabel>{getAttributeName(key, dataType)}</InputLabel>
213:               <OutlinedInput
214:                 label={getAttributeName(key, dataType)}
215:                 type={type === 'number' ? 'number' : 'text'}
216:                 value={getDisplayValue(value, dataType)}
217:                 onChange={(e) => updateAttribute(key, e.target.value, type, dataType)}
218:                 autoFocus={focusAttribute === key}
219:                 endAdornment={
220:                   <InputAdornment position="end">
221:                     <IconButton size="small" edge="end" onClick={() => deleteAttribute(key)}>
222:                       <CloseIcon fontSize="small" />
223:                     </IconButton>
224:                   </InputAdornment>
225:                 }
226:               />
227:             </FormControl>
228:           );
229:         })}
230:         <Button
231:           variant="outlined"
232:           color="primary"
233:           onClick={() => setAddDialogShown(true)}
234:           startIcon={<AddIcon />}
235:         >
236:           {t('sharedAdd')}
237:         </Button>
238:         <AddAttributeDialog
239:           open={addDialogShown}
240:           onResult={handleAddResult}
241:           definitions={definitions}
242:         />
243:       </AccordionDetails>
244:     </Accordion>
245:   );
246: };
247: 
248: export default EditAttributesAccordion;
